export interface RulesParseMetadata {
  sourceUrl: string;
  sourceSha256: string;
  generatedAt: string;
  version: string;
}

export interface ExtractedTextRun {
  text: string;
  x: number;
  y: number;
  page: number;
  fontSize?: number;
  internalHref?: string;
}

export interface RulesTextRun {
  text: string;
  href?: string;
}

export interface RulesBlock {
  type: 'paragraph' | 'heading';
  textRuns: RulesTextRun[];
}

export interface RulesSection {
  id: string;
  title: string;
  level: number;
  anchor: string;
  pageRef: number;
  blocks: RulesBlock[];
}

export interface TocEntry {
  title: string;
  anchor: string;
  level: number;
  order: number;
}

export interface RulesDocument {
  version: string;
  sourceUrl: string;
  sourceSha256: string;
  generatedAt: string;
  sections: RulesSection[];
  toc: TocEntry[];
}
